#!/usr/bin/env bash
# Activity and rest — 5 samples with a person wearing the ring (D-054, faces allowed).
G="$(cd "$(dirname "$0")" && pwd)/genref.sh"
cd "$(dirname "$0")/../../../.."
RM=design/ring-master; H=design/assets/v1/home; HAND=design/assets/v1/_archive/interior-draft1/masters/E-02-hand.png
R4=$RM/04-three-quarter-outer.png; CHAR=design/assets/v1/masters/C-01-character.png
run(){ [[ -f "$2" ]] && { echo "SKIP $2"; return; }; "$G" "$@" || echo "FAIL $2"; }
STYLE="Real editorial lifestyle photograph, not a 3D render, shot on a full-frame camera with a 50 mm or 85 mm lens, natural light only, true-to-life skin texture with natural pores, warm natural grade matching a warm cream and sage palette (cream plaster, oak, linen, soft green leaves, warm sunlight with leaf shadows), soft film-like tonality, fine grain. Calm, quiet, candid, not posed. The person is the SAME individual as in the attached character reference: same face, hair, skin tone and oatmeal linen shirt. The face may be visible but natural and candid, never looking into the camera; the ring stays the clear focal point."
RING="The person wears the smart ring from the attached ring reference on the INDEX finger of the LEFT hand, sitting between the knuckles, clearly visible: a slim smooth domed polished silver band about 7 mm wide with thin bright chamfered edges, realistic small scale on the finger, not thick or bulbous. The thumb and other fingers are bare."
AVOID="Avoid: looking into the camera, posed smile, ring on the thumb or on the wrong hand, oversized or bulbous ring, extra rings, watches, other jewelry, glowing lights, CGI or plastic skin, HDR, oversaturated colors, lens flare, vignette, text, logos, brand marks, posed model look."
SZ="--size 1080x1536"
run "Character reference portrait for a lifestyle series, real photograph, not a render. A woman in her early 30s with warm light-medium skin, natural freckles, shoulder-length dark brown hair loosely tied back with a few loose strands, minimal natural makeup, short natural unpolished nails, wearing a relaxed oatmeal linen shirt with sleeves slightly rolled. Half-body, three-quarter view, calm natural expression looking slightly off-camera, her left hand raised near her collar so the smart ring from the attached reference is clearly visible on her LEFT INDEX finger: slim smooth domed polished silver band about 7 mm wide, thin bright chamfered edges. Soft warm window light with gentle leaf shadows on a cream plaster wall behind. 4:5. Avoid: other jewelry, heavy makeup, posed smile, HDR, CGI skin, text." $CHAR --size 1232x1536 --ref $R4 --ref $HAND
run "$STYLE 07:40, Moving, a 25-minute morning walk. Candid medium shot from the side of the person walking, face in soft natural profile, the left hand swinging in the sharp foreground; along a quiet tree-lined path in low warm early-morning sun, about 3600K. The left arm swings naturally mid-stride, the hand relaxed and open, the silver ring catching the low sun; soft dappled leaf shadows fall across the linen sleeve; the path and greenery behind softly out of focus. Slight natural motion feel, hand sharp. Vertical 5:7. $RING $AVOID" $H/S3p-0740-moving-walk.png $SZ --ref $R4 --ref $CHAR --ref $HAND &
run "$STYLE 09:00, Resting, 40 minutes of quiet focus. Indoors at a light oak desk beside a window with a sheer linen curtain; warm leaf shadows play on a cream plaster wall. The person sits still, reading: the left hand rests flat and relaxed on the page of an open paper book, the silver ring clearly visible, a ceramic cup of coffee nearby. Medium close shot; the face is softly visible looking down at the book, the left hand sharp in the foreground. Calm morning light about 5000K. Vertical 5:7. $RING $AVOID Also avoid: readable text on the book pages." $H/S3p-0900-resting-focus.png $SZ --ref $R4 --ref $CHAR --ref $HAND &
run "$STYLE 10:30, Moving, a 15-minute stretch. Indoors by a sunny window, the person does a gentle standing side stretch: her LEFT arm reaches straight up overhead and leans slightly to her right, the left hand open and relaxed with fingers loosely together and the palm facing inward, the silver ring on the left index finger catching the light; her right hand rests on her hip. Eyes gently closed, calm face. Bright mid-morning sunlight about 5200K, crisp leaf shadows across the cream wall and linen shirt. Vertical 5:7, the raised left hand clearly visible in the upper part of the frame. Hands must be anatomically correct: each hand has exactly five digits, one thumb and four fingers, natural proportions and joints. $RING $AVOID Also avoid: interlaced fingers, extra or missing fingers, fused or bent-wrong fingers." $H/S3p-1030-moving-stretch.png $SZ --ref $R4 --ref $CHAR --ref $HAND &
wait
run "$STYLE 12:30, Resting, a 30-minute lunch. Outdoors at a small oak table under a tree, the table and the person's hands covered in soft dappled midday light and leaf shadows. A simple ceramic bowl of salad and a glass of water; the left hand rests relaxed on the table beside the bowl, the silver ring visible, the right hand holds a fork at rest. Medium shot at about 40 degrees; the person is softly visible, relaxed, looking away; the hand and ring sharp in the foreground. Midday light about 5600K. Vertical 5:7. $RING $AVOID" $H/S3p-1230-resting-lunch.png $SZ --ref $R4 --ref $CHAR --ref $HAND &
run "$STYLE 15:30, Moving, stairs and errands. Closer medium shot from the waist up, outdoors beside weathered stone steps and a cream plaster wall with climbing ivy, the person climbing the stairs in calm profile, carrying an undyed canvas tote with leafy greens and a baguette on her right shoulder. Her LEFT hand holds a dark metal handrail in a natural grip, seen from above and slightly in front: the palm rests on top of the rail, the four fingers curl over the far side of the rail, and the THUMB wraps around the near side of the rail and is clearly visible; the back of the hand faces the camera so the silver ring on the left index finger is clearly visible on top. The hand and ring are sharp in the foreground of the lower third. Warm afternoon sun from the right about 4200K, leaf shadows on the wall. Vertical 5:7. Hands must be anatomically correct: exactly five digits, one thumb and four fingers, natural proportions. $RING $AVOID Also avoid: missing thumb, palm-up or reversed hand, extra or missing fingers." $H/S3p-1530-moving-stairs.png $SZ --ref $R4 --ref $CHAR --ref $HAND &
wait
echo S3 PEOPLE DONE
